package cse.oop2.hotelreservation.server; public class AuthService { private final UserRepository userRepository; public AuthService(UserRepository r){userRepository=r;} public boolean login(String email,String password){String stored=userRepository.findPasswordByEmail(email);return stored!=null&&stored.equals(password);} public boolean signup(String name,String email,String password){if(userRepository.existsByEmail(email))return false;return userRepository.saveUser(name,email,password);} }
